    ("smc", "Small Magellanic Cloud", "", "", "SMC, PGC 7589", "galaxy", 0.877, -72.800, 2.2, "320x185", "Tuc", "200,000 ly", "Small Magellanic Cloud", "Smaller companion galaxy linked to the LMC by the Magellanic Bridge."),
